import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it)); k = int(next(it))
    pre = [int(next(it)) for _ in range(k)]
    used = [False]*(n+1)
    def fail():
        print(-1)
        sys.exit()
    # duplicates check
    for x in pre:
        if used[x]:
            fail()
        used[x]=True
    L = 0  # max of completed blocks
    if k==0:
        fail()
    # process first element
    first = pre[0]
    if first<=L:
        fail()
    s_curr = first
    need = first-1
    in_block = True
    if need==L:
        in_block=False
        L=s_curr
    # process rest of prefix
    for x in pre[1:]:
        if in_block:
            if x!=need or x<=L or used[x]:
                fail()
            need-=1
            if need==L:
                in_block=False
                L=s_curr
        else:
            if x<=L or used[x]:
                fail()
            s_curr = x
            need = x-1
            in_block=True
            if need==L:
                in_block=False
                L=s_curr
    res = pre[:]
    curr_max_unused = n
    while len(res)<n:
        if in_block:
            x = need
            if x<=0 or x<=L or used[x]:
                fail()
            res.append(x)
            used[x]=True
            need-=1
            if need==L:
                in_block=False
                L=s_curr
        else:
            while curr_max_unused>0 and used[curr_max_unused]:
                curr_max_unused-=1
            if curr_max_unused<=L:
                fail()
            x = curr_max_unused
            res.append(x)
            used[x]=True
            curr_max_unused-=1
            s_curr = x
            need = x-1
            in_block=True
            if need==L:
                in_block=False
                L=s_curr
    print(' '.join(map(str,res)))
if __name__ == "__main__":
    solve()

