def can_make(num: int) -> bool:
    digits = list(map(int, str(num)))
    used = [False] * n

    def dfs(pos: int) -> bool:
        if pos == len(digits):
            return True
        d = digits[pos]
        for i in range(n):
            if not used[i] and d in cubes[i]:
                used[i] = True
                if dfs(pos + 1):
                    return True
                used[i] = False
        return False

