            L=R=(size-1)//2
            p=(s+L)&1  # root parity
            # left subtree
            if L==0:
                left=1
            else:
                left=(odd[L][s] if p==0 else even[L][s])  # parity diff
            # right subtree
            if R==0:
                right=1
            else:
                right=(even[R][(s+L+1)&1] if p==0 else odd[R][(s+L+1)&1])  # parity same
            val=(left*right)%MOD
            if p==0:
                even[size][s]=(even[size][s]+val)%MOD
            else:
                odd[size][s]=(odd[size][s]+val)%MOD
        else:
